/** Where the construct stands in the value: alone, at the end, at the start, in the middle of text that looks like a credential. */
export const PLACEMENTS = [(text) => text, (text) => `S3cretValue${text}`, (text) => `${text}S3cretValue`, (text) => `S3cretValue${text}Tail9Value`];

/** Every generated command as [label, command, the text that has to be readable]. */
export function* constructCommands() {
  for (const [rule, quotes, build, inDouble = IN_DOUBLE, skip = []] of RULE_SHAPES) {
    for (const [shell, name, construct, inert = false, afterText = false] of CONSTRUCTS) {
      if (skip.includes(name)) continue;
      for (let index = 0; index < PLACEMENTS.length; index += 1) {
        for (const quote of quotes) {
          if ((inert && inDouble(quote)) || (afterText && (index === 0 || index === 2))) continue;
          const value = PLACEMENTS[index](construct);
          yield [`${rule} / ${shell}: ${name} / placement ${index} / quote ${quote || 'none'}`, build(inQuotes(quote, value), value, quote), construct];
        }
      }
    }
  }
}

