const VALUES_OF_A_WORD = [['zz9Needle7/run', true], ['./x/zz9Needle7', true], ['zz9Needle7', false], ['zz9Needle7.ps1', false], ['zz9Needle7\\run.ps1', true], ['ab:zz9Needle7/run', false], ['"zz9Needle7"/run', true], ['zz9Needle7"/run"', true], ["'zz9Needle7'/run", true]]; // [the value, whether it has a folder and no drive]
const FRONTS_OF_A_WORD = ['', 'a-', 'a.', 'a+', '}', '{', ')', '--', '-'];
/** Every such word: [label, command, needed], the words that have to stay readable, or (`hidden`) those whose value is that of a variable to every shell. */
function wordsLikeAssignments(hidden) {
  const found = [];
  for (const [place, kind] of PLACES_OF_A_WORD) for (const front of FRONTS_OF_A_WORD) for (const name of NAMES_OF_A_WORD) for (const sign of ['=', ':']) for (const [value, folder] of VALUES_OF_A_WORD) {
    if (/["']$/.test(place) && /["']/.test(value)) continue; // (the value would end the string)
    if ((front !== '' && (sign === ':' || VALUES_OF_A_WORD.findIndex((item) => item[0] === value) > 3)) || (sign === ':' && value.includes('ab:'))) continue; // (enough of them)
    if (place.endsWith('% { ') && /[{}]|^-/.test(front)) continue; // (an argument of % to bash)
    const flag = front.startsWith('-');
    if (flag && kind !== 'first') continue; // a flag of the word in front of it, or the next row of another program: not said here
    const assignment = front === '' && sign === '=' && (kind === 'assigns' || (kind === 'first' && !folder));
    const open = /["']$/.test(place) ? place.at(-1) : '';
    if (assignment === hidden) found.push([`a word like an assignment: ${JSON.stringify(place)} ${front}${name}${sign}${value}`, `${place}${front}${name}${sign}${value}${open}`, value.replace(/["']/g, '').replace(/[\\/]run(?:\.ps1)?$/, '').replace(/^ab:/, '').replace(/^\.\/x\//, '')]);
  }
  return found;
}

